    return typed_params

# We need get_typed_annotation to actually test the resolution
from fastapi.dependencies.utils import get_typed_annotation

def get_typed_signature_full_fixed(call):
    signature = inspect.signature(call)
    curr = call
    while hasattr(curr, "__wrapped__"):
        curr = curr.__wrapped__
    globalns = getattr(curr, "__globals__", {})

    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    return inspect.Signature(typed_params)

